let products = [
  { id: 1, sku: 'LAP-001', name: 'UltraBook Pro 15', price: 1299.99, inventory: 42, available: true },
  { id: 2, sku: 'LAP-002', name: 'NoteBook Air 13', price: 999.99, inventory: 0, available: false },
  { id: 3, sku: 'MON-001', name: 'UltraView 27" 4K', price: 549.99, inventory: 18, available: true },
  { id: 4, sku: 'MON-002', name: 'CurveDisplay 34" UW', price: 799.99, inventory: 7, available: true },
  { id: 5, sku: 'KEY-001', name: 'MechBoard TKL', price: 149.99, inventory: 55, available: true },
  { id: 6, sku: 'MOU-001', name: 'ErgoMouse Wireless', price: 79.99, inventory: 120, available: true },
  { id: 7, sku: 'HDK-001', name: 'DeskDock USB-C Hub', price: 89.99, inventory: 33, available: true },
  { id: 8, sku: 'CHR-001', name: 'QuickCharge 65W', price: 39.99, inventory: 0, available: false },
  { id: 9, sku: 'CAB-001', name: 'UltraLink USB-C Cable', price: 24.99, inventory: 200, available: true },
  { id: 10, sku: 'WLG-001', name: 'ErgoStand Adjustable', price: 59.99, inventory: 15, available: true },
]

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products.map((p) => ({ ...p }))
}

export async function syncProducts() {
  await new Promise((resolve) => setTimeout(resolve, 3000))

  products = products.map((p) => ({
    ...p,
    price: Math.round(p.price * (1 + (Math.random() - 0.5) * 0.1) * 100) / 100,
    inventory: Math.max(0, p.inventory + Math.floor((Math.random() - 0.4) * 8)),
    available: p.inventory > 0 ? Math.random() > 0.15 : Math.random() > 0.7,
  }))
}

