import { revalidateTag, unstable_cache } from 'next/cache'
import { getAllProducts } from '@/lib/db'

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['catalog-products'],
  { tags: ['products'] }
)

export default async function CatalogPage() {
  const products = await getCachedProducts()

  return (
    <main style={{ padding: '2rem', maxWidth: '960px', margin: '0 auto' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '1.5rem',
        }}
      >
        <h1 style={{ margin: 0 }}>Product Catalog</h1>
        <form action={syncAction}>
          <button
            type="submit"
            style={{
              padding: '0.6rem 1.2rem',
              fontSize: '0.95rem',
              cursor: 'pointer',
              background: '#0070f3',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th style={thStyle}>SKU</th>
            <th style={thStyle}>Name</th>
            <th style={thStyle}>Price</th>
            <th style={thStyle}>Inventory</th>
            <th style={thStyle}>Available</th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => (
            <tr key={p.id}>
              <td style={tdStyle}>{p.sku}</td>
              <td style={tdStyle}>{p.name}</td>
              <td style={tdStyle}>${p.price.toFixed(2)}</td>
              <td style={tdStyle}>{p.inventory}</td>
              <td style={tdStyle}>{p.available ? 'Yes' : 'No'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

async function syncAction() {
  'use server'

  const { syncProducts } = await import('@/lib/db')

  void syncProducts().then(() => {
    revalidateTag('products')
  })
}

const thStyle: React.CSSProperties = {
  textAlign: 'left',
  padding: '0.75rem',
  borderBottom: '2px solid #ddd',
  fontWeight: 600,
}

const tdStyle: React.CSSProperties = {
  padding: '0.75rem',
  borderBottom: '1px solid #eee',
}

